import{_ as s,o as a,c as e,ag as r}from"./chunks/framework.DUTPmUpA.js";const t="/_assets/Op4u0Oa.DGce-UhP.png",m=JSON.parse('{"title":"Использование фильтра заказов и других фильтров","description":"","frontmatter":{"title":"Использование фильтра заказов и других фильтров","author":"Perry","steamId":"76561198046986723","date":"26.06.2016"},"headers":[],"relativePath":"scripting/using-dota-filters.md","filePath":"scripting/using-dota-filters.md"}'),p={name:"scripting/using-dota-filters.md"};function l(i,n,o,c,d,u){return a(),e("div",null,[...n[0]||(n[0]=[r('<p>льзование фильтра заказов и других фильтров</p><h2 id="фильтры-в-целом" tabindex="-1">Фильтры в целом <a class="header-anchor" href="#фильтры-в-целом" aria-label="Permalink to &quot;Фильтры в целом&quot;">​</a></h2><p>В этом руководстве объясняется использование различных функций фильтра, имеющихся в настоящее время в API, и иллюстрируется это на небольшом примере в фильтре заказов.</p><p>В настоящее время в lua API доступно 9 фильтров, а именно:</p><ul><li><strong>AbilityTuningFilter</strong> — фильтрует способности и все значения, которые они используют при применении.</li><li><strong>BountyRunePickupFilter</strong> — Фильтрует подбор рун за добычу.</li><li><strong>DamageFilter</strong> — фильтрует события повреждения.</li><li><strong>ExecuteOrderFilter</strong> — фильтрует приказы (обычно отдаваемые игроками).</li><li><strong>ModifierGainedFilter</strong> — фильтрует события модификаторов, когда они впервые применяются к отряду.</li><li><strong>ModifyExperienceFilter</strong> — фильтрует изменения опыта.</li><li><strong>ModifyGoldFilter</strong> — Фильтрует модификации золота.</li><li><strong>RuneSpawnFilter</strong> — Фильтрует появление рун.</li><li><strong>TrackingProjectileFilter</strong> — фильтрует отслеживание запусков снарядов.</li></ul><p>Эти фильтры устанавливаются с использованием таких функций, как <code>CDOTABaseGameMode:SetExecuteOrderFilter(function, context)</code>. Проверьте <a href="https://github.com/TypeScriptToLua/Dota2Declarations/blob/master/dota-api.d.ts#L1193" target="_blank" rel="noreferrer">API declarations</a>, чтобы узнать точное имя функции для каждой функции. Затем фильтры можно снова очистить с помощью таких функций, как <code>CDOTABaseGameMode:ClearExecuteOrderFilter()</code> и подобных функций — опять же, см. <a href="https://github.com/TypeScriptToLua/Dota2Declarations/blob/master/dota-api.d.ts#L1193" target="_blank" rel="noreferrer">API declarations</a>.</p><h2 id="общая-идея" tabindex="-1">Общая идея <a class="header-anchor" href="#общая-идея" aria-label="Permalink to &quot;Общая идея&quot;">​</a></h2><p><strong>(Это самый важный раздел всего руководства)</strong> Движок Source 2 прослушивает события, генерируемые игроками или юнитами в игре. В движке имеется множество обработчиков, определяющих, что делать при получении определенного события. Фильтры анализируют эти события до того, как они достигнут движка, и имеют возможность принять решение не доставлять событие или, возможно, доставить измененную версию события.</p><p>Это можно объяснить аналогией с компанией, получающей почту. Обычной ситуацией является то, что компания (движок) получает почту (события) и читает их как обычно. Теперь представьте, что нанят новый секретарь (фильтр), который читает каждое полученное письмо и решает, достаточно ли важно письмо, чтобы его можно было обработать, или нет. Эта система проиллюстрирована на следующем рисунке:</p><p><img src="'+t+`" alt="Filtering visualized"></p><h2 id="фильтры-в-lua" tabindex="-1">Фильтры в Lua <a class="header-anchor" href="#фильтры-в-lua" aria-label="Permalink to &quot;Фильтры в Lua&quot;">​</a></h2><p>Итак, теперь мы знаем, как работают фильтры, и как их использовать? В этом объяснении будет использоваться <code>ExecuteOrderFilter</code>, имейте в виду, что все фильтры используют одну и ту же основную идею.</p><p>Первым шагом является установка фильтра с помощью вызова API <code>CDOTABaseGameMode:SetExecuteOrderFilter(function, context)</code>. Давайте проанализируем, что ожидает эта функция. Есть два параметра: <strong>Параметр: функция</strong> – функция фильтра. Эта функция является вашим настоящим фильтром. Он вызывается каждый раз, когда вызывается событие, которое вы фильтруете (в данном случае, когда поступает заказ). Функция фильтра получает два параметра: <strong>self</strong> и <strong>event</strong>. Параметр <strong>self</strong> — это всего лишь контекст функции (и он скрыт, если вы используете Dynamic_Wrap и оператор 😃. Действительно интересный параметр — это параметр <strong>event</strong>. Этот параметр содержит все данные события. Ваша функция фильтра должна просмотреть это событие и принять решение. Есть три возможных результата:</p><ol><li>Вы хотите ничего не делать и принимаете событие, вы <code>return true</code>.</li><li>Если вы хотите отклонить событие, оно будет выглядеть так, как будто этого события никогда не было, <code>return false</code>.</li><li>Вы хотите принять событие с некоторыми изменениями. Все, что вам нужно сделать, это <strong>изменить таблицу событий</strong> и <code>return true</code>.</li></ol><p><strong>Параметр: контекст</strong> – этот параметр передается в функцию фильтра как <strong>self</strong>.</p><h2 id="пример-1-отключение-глифа" tabindex="-1">Пример 1: отключение глифа <a class="header-anchor" href="#пример-1-отключение-глифа" aria-label="Permalink to &quot;Пример 1: отключение глифа&quot;">​</a></h2><p>Пришло время применить на практике то, что мы только что узнали. Мы знаем, что глиф — это приказ игрока, поэтому нам следует использовать фильтр приказов, чтобы отключить его. Все, что нам нужно сделать, это найти любые порядки глифов и вернуть false. Конечно, вы можете добавить любое ограничение на основе содержимого параметра события. Просто <code>DeepPrintTable( event )</code>, чтобы увидеть, какие данные вам доступны. Чтобы проверить, какие типы ордеров существуют, посмотрите <a href="https://moddota.com/api/#!/vscripts/dotaunitorder_t" target="_blank" rel="noreferrer">API</a>.</p><p>Обратите внимание, что в этом примере оператор : для <code>GameMode:OrderFilter</code> скрывает первый параметр (<code>self</code>).</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>--First set the filter to start catching events, usually this is in your init</span></span>
<span class="line"><span>GameRules:GetGameModeEntity():SetExecuteOrderFilter(Dynamic_Wrap(GameMode, &quot;OrderFilter&quot;), self)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--......................</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--Add the order filter to your game mode entity</span></span>
<span class="line"><span>function GameMode:OrderFilter(event)</span></span>
<span class="line"><span>    --Check if the order is the glyph type</span></span>
<span class="line"><span>    if event.order_type == DOTA_UNIT_ORDER_GLYPH then</span></span>
<span class="line"><span>        return false</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    --Return true by default to keep all other orders the same</span></span>
<span class="line"><span>    return true</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h2 id="пример-2-изменение-заказа" tabindex="-1">Пример 2: Изменение заказа <a class="header-anchor" href="#пример-2-изменение-заказа" aria-label="Permalink to &quot;Пример 2: Изменение заказа&quot;">​</a></h2><p>Этот пример имитирует своего рода «пьяное» состояние юнита, добавляя случайное смещение к любым приказам о движении. Код довольно прост: все, что вам нужно сделать, это изменить входящий заказ и вернуть true.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>--First set the filter to start catching events, usually this is in your init</span></span>
<span class="line"><span>GameRules:GetGameModeEntity():SetExecuteOrderFilter(Dynamic_Wrap(GameMode, &quot;OrderFilter&quot;), self)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--......................</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--Add the order filter to your game mode entity</span></span>
<span class="line"><span>function GameMode:OrderFilter(event)</span></span>
<span class="line"><span>    --Check if the order is the glyph type</span></span>
<span class="line"><span>    if event.order_type == DOTA_UNIT_ORDER_MOVE_TO_POSITION then</span></span>
<span class="line"><span>        local offsetVector = RandomVector(100)</span></span>
<span class="line"><span>        event.position_x = event.position_x + offsetVector.x</span></span>
<span class="line"><span>        event.position_y = event.position_y + offsetVector.y</span></span>
<span class="line"><span>        return true</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    --Return true by default to keep all other orders the same</span></span>
<span class="line"><span>    return true</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div>`,22)])])}const h=s(p,[["render",l]]);export{m as __pageData,h as default};
